INSERT IGNORE INTO noticias (titulo, slug, bajada, contenido, imagen_principal, categoria_id, autor_id, destacado, vistas, publicado, fecha_publicacion) VALUES
('Municipio de Valdivia aprueba plan de ciclovias para el centro historico', 'municipio-valdivia-ciclovias-centro', 'El proyecto contempla 12 km de ciclovias bidireccionales que conectaran los principales puntos de la ciudad.', '<p>El Concejo Municipal de Valdivia aprobo por unanimidad el plan de movilidad urbana sustentable que incluye 12 kilometros de ciclovias en el centro historico. La iniciativa tendra una inversion de 3.200 millones de pesos y se ejecutara en tres etapas durante 2026.</p><p>El alcalde destaco que el proyecto busca reducir el trafico vehicular en un 20% para 2027. Las obras incluiran senaletica, estacionamientos de bicicletas y zonas de descanso.</p>', 'https://picsum.photos/seed/ciclovias/800/500', 1, 1, 1, 8420, 1, '2026-05-08 08:00:00'),
('Intendente anuncia inversion de 8 mil millones en infraestructura regional', 'intendente-inversion-infraestructura-regional', 'Los fondos se destinaran a mejorar caminos rurales, puentes y obras de agua potable en las comunas mas vulnerables.', '<p>El Intendente de Los Rios anuncio una inversion de 8.000 millones de pesos para mejorar la infraestructura de la region durante 2026. Los recursos provienen del Fondo Nacional de Desarrollo Regional y se distribuiran entre 12 comunas.</p><p>Entre las obras destacan la reparacion de 45 km de caminos rurales en Panguipulli y Futrono, tres nuevos puentes y extension de redes de agua potable que beneficiara a 4.000 familias.</p>', 'https://picsum.photos/seed/inversion/800/500', 2, 1, 0, 5230, 1, '2026-05-08 09:15:00'),
('Feria Fluvial de Valdivia registra cifras record de visitantes esta temporada', 'feria-fluvial-valdivia-cifras-record', 'El emblematico mercado recibio mas de 120.000 visitas durante la temporada estival, un 40% mas que el ano anterior.', '<p>La iconica Feria Fluvial de Valdivia cerro su temporada estival con mas de 120.000 visitantes en tres meses, superando en 40% los registros anteriores. Los puesteros destacaron que las ventas crecieron significativamente en mariscos frescos, artesania y productos regionales.</p><p>Para la proxima temporada, la municipalidad planea renovar la infraestructura del mercado e incorporar nuevos servicios para visitantes.</p>', 'https://picsum.photos/seed/feria/800/500', 3, 1, 0, 9870, 1, '2026-05-07 10:30:00'),
('Deportes Valdivia golea 4-0 y avanza a semifinales del campeonato regional', 'deportes-valdivia-golea-semifinales-regional', 'Brilliant actuacion del equipo valdiviano que sello su boleto a la siguiente ronda con una contundente victoria.', '<p>Deportes Valdivia logro una brillante victoria por 4-0 ante su rival en el estadio municipal, clasificando a las semifinales del Campeonato Regional 2026. Los goles fueron anotados por Rodriguez (2), Henriquez y Castro en lo que fue una actuacion historica del equipo.</p><p>El tecnico del equipo califico el resultado como el mejor de la temporada y proyecto que con este nivel pueden aspirar al titulo. Mas de 8.000 hinchas llenaron el estadio para apoyar al equipo local.</p>', 'https://picsum.photos/seed/futbol/800/500', 4, 1, 1, 14320, 1, '2026-05-07 20:00:00'),
('Festival Internacional de Cine de Valdivia anuncia su programacion 2026', 'festival-cine-valdivia-programacion-2026', 'El evento cinefilotico mas importante del sur de Chile presentara mas de 80 peliculas de 35 paises.', '<p>El Festival Internacional de Cine de Valdivia presento su programacion oficial para la edicion 2026, que incluye mas de 80 peliculas de 35 paises. El evento se realizara del 6 al 13 de octubre y contara con secciones competitivas, homenajes y talleres cinematograficos.</p><p>Entre los platos fuertes destaca la presencia de directores internacionales reconocidos y el estreno sudamericano de varias producciones europeas. Las entradas ya estan disponibles en linea.</p>', 'https://picsum.photos/seed/cine/800/500', 5, 1, 0, 7640, 1, '2026-05-06 11:00:00'),
('Hospital Base de Valdivia implementa nuevo sistema de telemedicina regional', 'hospital-base-valdivia-telemedicina-regional', 'La tecnologia permitira atender a pacientes de zonas rurales sin necesidad de trasladarse a la ciudad.', '<p>El Hospital Base de Valdivia puso en marcha un innovador sistema de telemedicina que permitira a pacientes de comunas alejadas recibir atenciones medicas de especialistas sin necesidad de viajar. El proyecto beneficiara inicialmente a habitantes de Futrono, Lago Ranco y Panguipulli.</p><p>El director del hospital explico que el sistema reduce el tiempo de espera para atenciones de especialidad en un 60% y evita el traslado de pacientes en condiciones precarias. Se espera atender mas de 5.000 consultas mensuales.</p>', 'https://picsum.photos/seed/hospital/800/500', 6, 1, 0, 6180, 1, '2026-05-06 14:00:00'),
('Universidad Austral inaugura nuevo campus de innovacion y tecnologia', 'uach-nuevo-campus-innovacion-tecnologia', 'El campus albergara laboratorios de biotecnologia, inteligencia artificial y emprendimiento regional.', '<p>La Universidad Austral de Chile inauguro su nuevo Campus de Innovacion y Tecnologia, un moderno complejo de 12.000 metros cuadrados que albergara laboratorios de biotecnologia, inteligencia artificial, robotica y un hub de emprendimiento regional.</p><p>El rector destaco que la inversion de 15.000 millones de pesos posiciona a la UACh como un referente de investigacion e innovacion en el sur del pais. Mas de 1.200 estudiantes y 80 investigadores usaran las nuevas instalaciones.</p>', 'https://picsum.photos/seed/campus/800/500', 7, 1, 0, 8950, 1, '2026-05-05 10:00:00'),
('Ruta de los Lagos incrementa llegada de turistas extranjeros en un 45%', 'ruta-lagos-turistas-extranjeros-45-por-ciento', 'El corredor turistico Chile-Argentina registra su mejor temporada con visitantes de Europa, EEUU y Asia.', '<p>La Ruta de los Lagos Chile-Argentina registro su mejor temporada con un incremento del 45% en la llegada de turistas extranjeros respecto al ano anterior. Los principales mercados emisores fueron Alemania, Estados Unidos y Brasil, seguidos por turistas de Australia y Japon.</p><p>Los operadores turisticos de Valdivia, Osorno y Puerto Montt reportaron ocupacion hotelera maxima durante los meses de enero y febrero. Las atracciones mas visitadas fueron el lago Llanquihue, el volcan Osorno y la Feria Fluvial de Valdivia.</p>', 'https://picsum.photos/seed/lagos/800/500', 8, 1, 0, 11230, 1, '2026-05-05 12:30:00'),
('Proyecto de reforestacion recuperara 5.000 hectareas de bosque nativo en Los Rios', 'reforestacion-5000-hectareas-bosque-nativo-los-rios', 'La iniciativa publico-privada plantara especies nativas como coihue, olivillo y canelo para restaurar ecosistemas degradados.', '<p>Una iniciativa publico-privada iniciara la plantacion de 5.000 hectareas de bosque nativo en la region de Los Rios, con especies como coihue, olivillo, canelo y tepa. El proyecto cuenta con financiamiento del Ministerio del Medio Ambiente y empresas privadas comprometidas con la sustentabilidad.</p><p>La iniciativa busca restaurar ecosistemas degradados por la ganaderia extensiva y los incendios forestales, ademas de crear corredores biologicos para la fauna nativa de la region.</p>', 'https://picsum.photos/seed/bosque/800/500', 9, 1, 0, 7320, 1, '2026-05-04 09:00:00'),
('Startup valdiviana desarrolla app para monitoreo de calidad del aire en tiempo real', 'startup-valdiviana-app-monitoreo-calidad-aire', 'La aplicacion conecta con sensores distribuidos en la ciudad y entrega alertas de contaminacion por material particulado.', '<p>Una startup fundada por egresados de la Universidad Austral de Chile lanzo una novedosa aplicacion movil que permite monitorear la calidad del aire en Valdivia en tiempo real. La app se conecta con una red de 25 sensores distribuidos por la ciudad y entrega alertas cuando los niveles de material particulado superan los limites recomendados.</p><p>El emprendimiento ya cuenta con 15.000 usuarios activos y ha llamado la atencion de otras ciudades del sur de Chile que buscan implementar el sistema. Los fundadores proyectan expandirse a Osorno, Puerto Montt y Temuco durante 2026.</p>', 'https://picsum.photos/seed/app/800/500', 10, 1, 0, 9140, 1, '2026-05-04 15:00:00'),
('Consejo Regional aprueba presupuesto para recuperacion de humedales urbanos de Valdivia', 'core-presupuesto-recuperacion-humedales-valdivia', 'Los humedales son considerados patrimonio natural de la ciudad y fuente de biodiversidad unica en el mundo.', '<p>El Consejo Regional de Los Rios aprobo un presupuesto de 2.800 millones de pesos para la recuperacion y proteccion de los humedales urbanos de Valdivia, reconocidos como un patrimonio natural unico en el mundo por su biodiversidad y belleza paisajistica.</p><p>El plan contempla la recuperacion de vegetacion nativa, la construccion de senderos para visitantes y la instalacion de centros de interpretacion ambiental. Ademas, se estableceran zonas de amortiguacion para proteger los humedales del avance urbano.</p>', 'https://picsum.photos/seed/humedal/800/500', 9, 1, 0, 5670, 1, '2026-05-03 11:00:00'),
('Maratón Internacional de Valdivia reunira a 8.000 corredores de 15 paises', 'maraton-internacional-valdivia-2026', 'La tradicional carrera recorrera los humedales, el centro historico y el borde costero del rio Calle-Calle.', '<p>La Maraton Internacional de Valdivia 2026 ya tiene 8.000 inscripciones confirmadas de corredores provenientes de 15 paises. El evento se realizara el proximo 21 de junio y recorrera un circuito de 42 kilometros que incluye los humedales, el centro historico, el Parque Saval y el borde costero del rio Calle-Calle.</p><p>Ademas de la maraton oficial, habra categorias de 10K y 5K para corredores recreativos. Los organizadores esperan que el evento genere un impacto economico de 3.000 millones de pesos para la ciudad.</p>', 'https://picsum.photos/seed/maraton/800/500', 4, 1, 0, 12450, 1, '2026-05-03 16:00:00'),
('Nuevo ferry conectara Valdivia con isla Mancera en servicio permanente', 'nuevo-ferry-valdivia-isla-mancera-permanente', 'El servicio operara cinco veces al dia y reducira el tiempo de viaje a la historica isla a solo 20 minutos.', '<p>La Empresa de Transporte Maritimo del Sur inauguro el servicio permanente de ferry entre Valdivia e Isla Mancera, operando cinco frecuencias diarias con una embarcacion de 80 pasajeros y capacidad para 8 vehiculos. El viaje toma solo 20 minutos y cuesta 2.500 pesos por persona.</p><p>La isla Mancera, que alberga el Fuerte de San Pedro de Alcantara del siglo XVII, es uno de los destinos turisticos mas emblematicos de la region pero habia sido de dificil acceso por la falta de conectividad regular.</p>', 'https://picsum.photos/seed/ferry/800/500', 8, 1, 0, 8760, 1, '2026-05-02 10:00:00'),
('Liceo Cientifico-Humanista de Valdivia gana olimpiada nacional de matematicas', 'liceo-valdivia-olimpiada-nacional-matematicas', 'Estudiantes representaron a la region de Los Rios y se impusieron ante establecimientos de todo Chile.', '<p>Estudiantes del Liceo Cientifico-Humanista de Valdivia obtuvieron el primer lugar en la Olimpiada Nacional de Matematicas 2026, superando a establecimientos de Santiago, Concepcion y Antofagasta. El equipo valdiviano, compuesto por seis estudiantes de segundo y tercero medio, resolvio los problemas mas complejos de la competencia.</p><p>El logro fue celebrado por el sostenedor del establecimiento y las autoridades educacionales de la region. Los estudiantes ganadores recibiran becas universitarias y representaran a Chile en la Olimpiada Iberoamericana de Matematicas.</p>', 'https://picsum.photos/seed/liceo/800/500', 7, 1, 0, 6890, 1, '2026-05-02 14:00:00'),
('Caleta Niebla abre temporada de surf con record de participantes en festival', 'caleta-niebla-temporada-surf-record-participantes', 'Mas de 500 surfistas de Chile y Argentina disputaron las olas del Pacifico en el tradicional encuentro costero.', '<p>La Caleta Niebla, ubicada a 13 kilometros de Valdivia en la desembocadura del rio Calle-Calle, abrio su temporada de surf con el tradicional festival que reunio a mas de 500 surfistas de Chile y Argentina. Las olas del Pacifico ofrecieron condiciones excepcionales durante los tres dias del evento.</p><p>El festival incluyo competencias de surf, bodyboard y longboard en distintas categorias. Ademas de las competencias, se realizaron clinicas de surf para principiantes y actividades culturales para los visitantes.</p>', 'https://picsum.photos/seed/surf/800/500', 8, 1, 0, 10230, 1, '2026-05-01 09:00:00'),
('Empresa salmonera anuncia 500 nuevos empleos permanentes en la region de Los Rios', 'empresa-salmonera-500-nuevos-empleos-los-rios', 'La inversion de 45 millones de dolares ampliara la planta procesadora y el centro de cultivo en el lago Maihue.', '<p>Una empresa salmonera de capitales noruegos anuncio una inversion de 45 millones de dolares para ampliar sus operaciones en la region de Los Rios, lo que generara 500 nuevos empleos permanentes y 200 puestos de trabajo indirecto. La expansion incluye la ampliacion de la planta procesadora en Futrono y el desarrollo de nuevas concesiones acuicolas en el lago Maihue.</p><p>La empresa se comprometio a contratar preferentemente a trabajadores de la region y a cumplir con estandares ambientales internacionales para minimizar el impacto en los ecosistemas lacustres.</p>', 'https://picsum.photos/seed/salmon/800/500', 3, 1, 0, 7450, 1, '2026-04-30 11:30:00'),
('Arqueologos descubren sitio mapuche de 2.000 anos en ribera del rio Cruces', 'arqueologos-sitio-mapuche-2000-anos-rio-cruces', 'El hallazgo incluye ceramicas, instrumentos de piedra y restos organicos que revelan asentamientos prehistoricos desconocidos.', '<p>Un equipo de arqueologos de la Universidad Austral de Chile descubrio un importante sitio arqueologico mapuche de aproximadamente 2.000 anos de antiguedad en la ribera norte del rio Cruces, a pocos kilometros de Valdivia. El hallazgo incluye ceramicas decoradas, instrumentos de piedra tallada, puntas de proyectil y restos organicos que seran sometidos a datacion por carbono 14.</p><p>Los investigadores senalan que el descubrimiento podria revelar informacion inedita sobre los patrones de asentamiento de las comunidades mapuche antes de la llegada de los espanoles a la region.</p>', 'https://picsum.photos/seed/arqueologia/800/500', 5, 1, 0, 9320, 1, '2026-04-29 10:00:00'),
('Nueva linea de buses electricos recorre el centro de Valdivia desde este lunes', 'nueva-linea-buses-electricos-valdivia', 'Los vehiculos de tecnologia cero emisiones cubriran el recorrido entre el terminal y el hospital en 18 minutos.', '<p>Desde este lunes, la ciudad de Valdivia cuenta con su primera linea de buses electricos que recorre el eje central desde el Terminal de Buses hasta el Hospital Base, pasando por el centro comercial y la Universidad Austral. Los cinco buses de la flota tienen capacidad para 80 pasajeros y funcionan con baterias de litio que se recargan en horario nocturno.</p><p>El proyecto es parte del Plan de Movilidad Sustentable de la municipalidad y se espera incorporar cinco buses mas antes de fin de ano. El costo del pasaje se mantiene igual al del transporte convencional.</p>', 'https://picsum.photos/seed/bus/800/500', 1, 1, 0, 11670, 1, '2026-04-28 08:00:00'),
('Vendimia en vinedos de los Rios anuncia su mejor cosecha de la decada', 'vendimia-vinedos-los-rios-mejor-cosecha-decada', 'Las condiciones climaticas excepcionales permitieron una uva de alta calidad con alto contenido de azucar y aromas complejos.', '<p>Productores vitivinicolas de la region de Los Rios reportaron la mejor cosecha de la decada gracias a las excepcionales condiciones climaticas del verano 2026. Las variedades Pinot Noir, Riesling y Gewurztraminer, que se adaptan mejor al clima frio y humedo del sur de Chile, lograron niveles de maduracion y complejidad aromatica sin precedentes.</p><p>Los viticultores esperan que esta cosecha impulse definitivamente el reconocimiento internacional de los vinos del sur de Chile y atraiga nuevos inversores al sector.</p>', 'https://picsum.photos/seed/vino/800/500', 3, 1, 0, 8130, 1, '2026-04-27 12:00:00'),
('Cruz Roja lanza campana de donacion de sangre ante importante deficit en la region', 'cruz-roja-donacion-sangre-deficit-los-rios', 'Los bancos de sangre de la region estan al 40% de su capacidad y urgen donaciones voluntarias de todos los grupos sanguineos.', '<p>La Cruz Roja Chilena hizo un llamado urgente a la comunidad de Los Rios a donar sangre ante un deficit critico en los bancos de sangre regionales. Los depositos se encuentran al 40% de su capacidad ideal, lo que pone en riesgo la atencion de cirugias de emergencia y tratamientos oncologicos.</p><p>Los centros de donacion ubicados en el Hospital Base de Valdivia y en los hospitales de Osorno y La Union reciben donantes de lunes a sabado entre las 08:30 y las 13:00 horas. Solo es necesario tener entre 18 y 65 anos, pesar mas de 50 kg y estar en buen estado de salud.</p>', 'https://picsum.photos/seed/sangrecruz/800/500', 6, 1, 0, 15780, 1, '2026-04-26 09:00:00');
